prompt --application/shared_components/security/authorizations/delete_allowed
begin
wwv_flow_imp_shared.create_security_scheme(
 p_id=>wwv_flow_imp.id(10502890588268706)
,p_name=>'Delete_allowed'
,p_scheme_type=>'NATIVE_FUNCTION_BODY'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'a number;',
'U VARCHAR2(45):=V(''APP_USER'');',
'P NUMBER:=:APP_PAGE_ID;',
'begin',
'select 1 into a from user_right t,rights r where upper(t.username)=upper (u)',
'and r.page_no=p and t.delete_allowed=''Y'' and t.right_id=r.right_id;',
'return true;',
'exception',
'when others then',
'return false;',
'end;'))
,p_error_message=>'You are not possible this action.'
,p_version_scn=>13298211
,p_caching=>'NOCACHE'
);
end;
