||'ht: #EAF4FF;\n\n    --at-green: #159447;\n    --at-green-dark: #10783A;\n    --at-green-light: #EAF8F0;\n\n    --at-bg: #F5F8FB;\n    --at-white: #FFFFFF;\n\n    --at-border: #D9E2EC;\n    --at-border-dark: #C4D0DC;\n\n    --at-text: #18324A;\n    --'
||'at-muted: #64748B;\n\n    --at-danger: #DC3545;\n    --at-danger-dark: #B42332;\n\n    --at-warning: #E6A700;\n\n    --at-gray: #64748B;\n    --at-gray-dark: #475569;\n\n    --at-shadow:\n        0 4px 16px rgba(7,55,99,.09);\n\n    --at-radius: 9px;'
||'\n}\n\n\n/* =========================================================\n   2. PAGE\n========================================================= */\n\nhtml,\nbody {\n    background-color: var(--at-bg);\n}\n\n.t-Body {\n    background-color: var(--at-bg) '
||'!important;\n}\n\n.t-Body-main {\n    background-color: var(--at-bg) !important;\n}\n\n.t-Body-content {\n    background-color: var(--at-bg) !important;\n}\n\n.t-Body-contentInner {\n    background-color: transparent !important;\n}\n\n\n/* =========='
||'===============================================\n   3. HEADER\n========================================================= */\n\n.t-Header {\n    background:\n        linear-gradient(\n            135deg,\n            var(--at-navy),\n            var(-'
||'-at-blue)\n        ) !important;\n\n    border-bottom:\n        3px solid var(--at-green) !important;\n\n    box-shadow:\n        0 3px 12px rgba(7,55,99,.18);\n}\n\n.t-Header-branding,\n.t-Header-nav {\n    background: transparent !important;\n}\n\n'
||'.t-Header-logo,\n.t-Header-logo-text {\n    color: #FFFFFF !important;\n}\n\n.t-Header .t-Button {\n    color: #FFFFFF !important;\n}\n\n.t-Header .t-Button .t-Icon {\n    color: #FFFFFF !important;\n}\n\n.t-NavigationBar-item a {\n    color: #FFFFFF'
