' FUNCTION autonamefuc(',
'    p_username IN VARCHAR2,',
'    p_password IN VARCHAR2',
') RETURN BOOLEAN',
'IS',
'    l_count NUMBER;',
'BEGIN',
'',
'    SELECT COUNT(*)',
'      INTO l_count',
'      FROM login',
'     WHERE UPPER(TRIM(username)) = UPPER(TRIM(p_username))',
'       AND userpassword =',
'           RAWTOHEX(',
'               DBMS_CRYPTO.HASH(',
'                   UTL_RAW.CAST_TO_RAW(p_password),',
'                   DBMS_CRYPTO.HASH_MD5',
'               )',
'           )',
'       AND UPPER(TRIM(status)) = ''ACTIVE'';',
'',
'    RETURN l_count = 1;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        RETURN FALSE;',
'END;',
''))
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>12676146
);
end;
