wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9740768344207030)
,p_plug_name=>'All_CATEGORY SUMMSRY'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ''All Employees'' AS TITLE,',
'       COUNT(*) AS TOTAL',
'FROM EMP',
'',
'UNION ALL',
'',
'SELECT ''All Tenants'' AS TITLE,',
'       COUNT(*) AS TOTAL',
'FROM TENANT',
'',
'UNION ALL',
'',
'SELECT ''All Buildings'' AS TITLE,',
'       COUNT(*) AS TOTAL',
'FROM BUILDING',
'',
'UNION ALL',
'',
'SELECT ''All Rental Contracts'' AS TITLE,',
'       COUNT(*) AS TOTAL',
'FROM RENTAL',
'',
'UNION ALL',
'',
'SELECT ''All Rental Services'' AS TITLE,',
'       COUNT(*) AS TOTAL',
