wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9740966866207032)
,p_plug_name=>'Today Summary'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>40
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ''Total Rental Payments Today'' AS CARD_TITLE,',
'       COUNT(*) AS CARD_TEXT,',
'       NULL AS CARD_SUBTEXT',
'FROM RENTAL_PAYMENT',
'WHERE PAYMENT_DATE >= TRUNC(SYSDATE)',
'  AND PAYMENT_DATE < TRUNC(SYSDATE) + 1',
'',
'UNION ALL',
'',
'SELECT ''Rent Billed Today'',',
'       NVL(SUM(RENT), 0),',
'       NULL',
'FROM RENTAL_PAYMENT',
'WHERE PAYMENT_DATE >= TRUNC(SYSDATE)',
'  AND PAYMENT_DATE < TRUNC(SYSDATE) + 1',
'',
'UNION ALL',
'',
'SELECT ''Rent Paid Today'',',
'       NVL(SUM(AMOUNT_PAID), 0),',
'       NULL',
'FROM RENTAL_PAYMENT',
'WHERE PAYMENT_DATE >= TRUNC(SYSDATE)',
'  AND PAYMENT_DATE < TRUNC(SYSDATE) + 1',
'',
'UNION ALL',
'',
'SELECT ''Rent Balance Today'',',
'       GREATEST(',
'           NVL(SUM(NVL(RENT, 0) - NVL(AMOUNT_PAID, 0)), 0),',
'           0',
'       ),',
'       NULL',
'FROM RENTAL_PAYMENT',
'WHERE PAYMENT_DATE >= TRUNC(SYSDATE)',
'  AND PAYMENT_DATE < TRUNC(SYSDATE) + 1',
'',
'UNION ALL',
'',
'SELECT ''Electricity Money Today'',',
'       NVL(',
'           SUM(',
'               (NVL(CURRENT_METER, 0) - NVL(PREVIOUS_METER, 0))',
'               * NVL(METER_RATE, 0)',
'           ),',
'           0',
'       ),',
'       NULL',
'FROM RENTAL_PAYMENT',
'WHERE PAYMENT_DATE >= TRUNC(SYSDATE)',
'  AND PAYMENT_DATE < TRUNC(SYSDATE) + 1',
'',
'UNION ALL',
'',
'SELECT ''Total Utility Charges Today'',',
'       NVL(',
'           SUM(',
'               (NVL(CURRENT_METER, 0) - NVL(PREVIOUS_METER, 0))',
'               * NVL(METER_RATE, 0)',
'               + NVL(CLEANER, 0)',
'           ),',
'           0',
'       ),',
'       NULL',
'FROM RENTAL_PAYMENT',
'WHERE PAYMENT_DATE >= TRUNC(SYSDATE)',
'  AND PAYMENT_DATE < TRUNC(SYSDATE) + 1'))
,p_plug_source_type=>'PLUGIN_COM.ORACLE.APEX.BADGE_LIST'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'CARD_TITLE',
  'attribute_02', 'CARD_TEXT',
  'attribute_05', '0',
  'attribute_06', 'L',
  'attribute_07', 'DOT',
  'attribute_08', 'N')).to_clob
);
