'SELECT',
'    CASE',
'        WHEN UPPER(STATUS) = ''AVAILABLE'' THEN ''Available''',
'        WHEN UPPER(STATUS) = ''RENTED'' THEN ''Rented''',
'        WHEN UPPER(STATUS) = ''MAINTENANCE'' THEN ''Maintenance''',
'        ELSE ''Other''',
'    END AS LABEL,',
'    COUNT(*) AS TOTAL',
'FROM RENTAL_SERVICES',
'GROUP BY',
'    CASE',
'        WHEN UPPER(STATUS) = ''AVAILABLE'' THEN ''Available''',
'        WHEN UPPER(STATUS) = ''RENTED'' THEN ''Rented''',
'        WHEN UPPER(STATUS) = ''MAINTENANCE'' THEN ''Maintenance''',
'        ELSE ''Other''',
'    END',
'ORDER BY LABEL;'))
,p_items_value_column_name=>'TOTAL'
,p_items_label_column_name=>'LABEL'
,p_items_label_rendered=>false
