wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9741739287207040)
,p_plug_name=>'Tenant Rent Report'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4501440665235496320
,p_plug_display_sequence=>20
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    CURSOR c_report (p_tenant_id NUMBER) IS',
'        SELECT',
'            t.tenant_name,',
'            rp.month_of_payment,',
'',
'            NVL(rp.previous_meter, 0) AS previous_meter,',
'            NVL(rp.current_meter, 0) AS current_meter,',
'',
'            NVL(rp.current_meter, 0)',
'              - NVL(rp.previous_meter, 0) AS unit_consumed,',
'',
'            (NVL(rp.current_meter, 0)',
'              - NVL(rp.previous_meter, 0))',
'              * NVL(rp.meter_rate, 0) AS utility_charge,',
'',
'            NVL(rp.rent, 0) AS rent,',
'            NVL(rp.cleaner, 0) AS cleaner_charge,',
'',
'            NVL(rp.rent, 0)',
'              + ((NVL(rp.current_meter, 0)',
'              - NVL(rp.previous_meter, 0))',
'              * NVL(rp.meter_rate, 0))',
'              + NVL(rp.cleaner, 0) AS total,',
'',
'            NVL(rp.amount_paid, 0) AS payment_paid,',
'',
'            GREATEST(',
'                NVL(rp.rent, 0)',
'                + ((NVL(rp.current_meter, 0)',
'                - NVL(rp.previous_meter, 0))',
'                * NVL(rp.meter_rate, 0))',
'                + NVL(rp.cleaner, 0)',
'                - NVL(rp.amount_paid, 0),',
'                0',
'            ) AS balance',
'',
'        FROM tenant t',
'        JOIN rental r',
'          ON r.tenant_id = t.tenant_id',
'        JOIN rental_payment rp',
'          ON rp.rental_id = r.rental_id',
'        WHERE t.tenant_id = p_tenant_id',
'        ORDER BY rp.month_of_payment;',
'',
'    v_row          c_report%ROWTYPE;',
'    v_tenant_name  VARCHAR2(4000);',
'    v_total        NUMBER := 0;',
'    v_paid         NUMBER := 0;',
'    v_balance      NUMBER := 0;',
'    v_count        PLS_INTEGER := 0;',
'    v_html         CLOB;',
'',
'    FUNCTION fmt(p_value NUMBER) RETURN VARCHAR2 IS',
'    BEGIN',
'        RETURN TO_CHAR(',
'            NVL(p_value, 0),',
'            ''FM999G999G999G990D00'',',
'            ''NLS_NUMERIC_CHARACTERS=''''.,''''''',
'        );',
'    END fmt;',
'',
'BEGIN',
'    -- No tenant selected',
'    IF :P30_TENANT_ID IS NULL THEN',
'        RETURN q''~',
'            <div class="rent-notice">',
'                Please select a tenant to display the rent report.',
'            </div>',
'        ~'';',
'    END IF;',
'',
'    -- First pass: calculate totals',
'    FOR r IN c_report(:P30_TENANT_ID) LOOP',
'        v_count := v_count + 1;',
'',
'        IF v_count = 1 THEN',
'            v_tenant_name := r.tenant_name;',
'        END IF;',
'',
'        v_total   := v_total + r.total;',
'        v_paid    := v_paid + r.payment_paid;',
'        v_balance := v_balance + r.balance;',
'    END LOOP;',
'',
'    -- No payment records',
'    IF v_count = 0 THEN',
'        RETURN q''~',
'            <div class="rent-notice">',
'                No payment records were found for this tenant.',
'                Please check the selected tenant and payment records.',
'            </div>',
'        ~'';',
'    END IF;',
'',
'    -- Start HTML report',
'    v_html := q''~',
'    <style>',
'      .rent-report {',
'        font-family: Arial, sans-serif;',
'        color: #17243b;',
'        background: #fff;',
'        border: 1px solid #e2e8f0;',
'        border-radius: 16px;',
'        overflow: hidden;',
'        box-shadow: 0 8px 28px rgba(20,45,80,.08);',
'      }',
'      .rent-head {',
'        padding: 28px;',
'        background: linear-gradient(120deg,#12345a,#2468a0);',
'        color: #fff;',
'        display: flex;',
'        justify-content: space-between;',
'        gap: 16px;',
'        align-items: center;',
'      }',
'      .rent-head h2 { margin: 0 0 8px; font-size: 25px; }',
'      .rent-head p { margin: 0; color: #dbeafe; font-size: 13px; }',
'      .rent-print {',
'        background: #fff;',
'        color: #17416c;',
'        border: 0;',
'        border-radius: 9px;',
'        padding: 12px 18px;',
'        font-weight: bold;',
'        cursor: pointer;',
'        white-space: nowrap;',
'      }',
'      .rent-body { padding: 22px; }',
'      .rent-summary {',
'        display: grid;',
'        grid-template-columns: repeat(3,minmax(0,1fr));',
'        gap: 12px;',
'        margin-bottom: 22px;',
'      }',
'      .rent-card {',
'        padding: 16px;',
'        border: 1px solid #e3eaf3;',
'        border-radius: 12px;',
'        background: #f8fbff;',
'        min-width: 0;',
'      }',
'      .rent-card span {',
'        display: block;',
'        color: #64748b;',
'        font-size: 12px;',
'        margin-bottom: 8px;',
'      }',
'      .rent-card strong {',
'        font-size: 20px;',
'        color: #173b6c;',
'        overflow-wrap: anywhere;',
'      }',
'      .rent-table-wrap { width: 100%; overflow-x: auto; }',
'      .rent-table {',
'        width: 100%;',
'        border-collapse: collapse;',
'        font-size: 12px;',
'      }',
'      .rent-table th {',
'        background: #edf4fc;',
'        color: #234568;',
'        text-align: left;',
'        padding: 13px 10px;',
'        border-bottom: 1px solid #dbe5f0;',
'      }',
'      .rent-table td {',
'        padding: 13px 10px;',
'        border-bottom: 1px solid #edf1f6;',
'      }',
'      .rent-table tbody tr:nth-child(even) { background: #f9fbfe; }',
'      .rent-table .money { text-align: right; white-space: nowrap; }',
'      .rent-table tfoot td {',
'        background: #edf4fc;',
'        font-weight: bold;',
'      }',
'      .rent-balance { color: #c24145; font-weight: bold; }',
'      .rent-paid { color: #16805d; font-weight: bold; }',
'      .rent-notice {',
'        padding: 18px;',
'        margin: 20px;',
'        background: #fff7e6;',
'        border: 1px solid #f3d9a5;',
'        border-radius: 10px;',
'        color: #805b16;',
'      }',
'      .rent-foot {',
'        display: flex;',
'        justify-content: space-between;',
'        gap: 12px;',
'        padding: 18px 22px;',
'        color: #64748b;',
'        font-size: 11px;',
'        border-top: 1px solid #e5ebf3;',
'      }',
'      @media(max-width:700px) {',
'        .rent-head { align-items: flex-start; flex-direction: column; }',
'        .rent-summary { grid-template-columns: 1fr; }',
'        .rent-body { padding: 12px; }',
'      }',
'      @media print {',
'        @page { size: landscape; margin: 12mm; }',
'        body { background: #fff !important; }',
'        body * { visibility: hidden !important; }',
'        .rent-report, .rent-report * { visibility: visible !important; }',
'        .rent-report {',
'          position: absolute !important;',
'          left: 0 !important;',
'          top: 0 !important;',
'          width: 100% !important;',
'          border: 0 !important;',
'          box-shadow: none !important;',
'          border-radius: 0 !important;',
'        }',
'        .rent-print, .t-Header, .t-Footer, .t-Body-nav,',
'        .t-Body-actions, .t-Body-title { display: none !important; }',
'        .rent-head {',
'          background: #12345a !important;',
'          color: #fff !important;',
'          print-color-adjust: exact;',
'          -webkit-print-color-adjust: exact;',
'        }',
'        .rent-table { font-size: 10px; }',
'        .rent-table th, .rent-table tfoot td {',
'          print-color-adjust: exact;',
'          -webkit-print-color-adjust: exact;',
'        }',
'        .rent-table tr { break-inside: avoid; }',
'      }',
'    </style>',
'',
'    <div class="rent-report">',
'      <div class="rent-head">',
'        <div>',
'          <h2>Tenant Rent Statement</h2>',
unistr('          <p>Sarvary Building Management System \00B7 Tenant Payment Bill</p>'),
'        </div>',
'        <button type="button" class="rent-print"',
'          onclick="window.print()">&#128438; Print Report</button>',
'      </div>',
'',
'      <div class="rent-body">',
'        <div class="rent-summary">',
'          <div class="rent-card">',
'            <span>Tenant Name</span>',
'            <strong>~''',
'        || APEX_ESCAPE.HTML(v_tenant_name)',
'        || q''~</strong>',
'          </div>',
'',
'          <div class="rent-card">',
'            <span>Total Charges</span>',
'            <strong>~''',
'        || fmt(v_total)',
'        || q''~ AFN</strong>',
'          </div>',
'',
'          <div class="rent-card">',
'            <span>Total Paid</span>',
'            <strong class="rent-paid">~''',
'        || fmt(v_paid)',
'        || q''~ AFN</strong>',
'          </div>',
'',
'          <div class="rent-card">',
'            <span>Outstanding Balance</span>',
'            <strong class="rent-balance">~''',
'        || fmt(v_balance)',
'        || q''~ AFN</strong>',
'          </div>',
'        </div>',
'',
'        <div class="rent-table-wrap">',
'          <table class="rent-table">',
'            <thead>',
'              <tr>',
'                <th>Payment Month</th>',
'                <th>Previous Meter</th>',
'                <th>Current Meter</th>',
'                <th>Units Consumed</th>',
'                <th class="money">Utility (AFN)</th>',
'                <th class="money">Rent (AFN)</th>',
'                <th class="money">Cleaner (AFN)</th>',
'                <th class="money">Total (AFN)</th>',
'                <th class="money">Paid (AFN)</th>',
'                <th class="money">Balance (AFN)</th>',
'              </tr>',
'            </thead>',
'            <tbody>',
'    ~'';',
'',
'    -- Second pass: output every payment row',
'    FOR r IN c_report(:P30_TENANT_ID) LOOP',
'        v_html := v_html',
'            || ''<tr><td>''',
'            || APEX_ESCAPE.HTML(',
'                   NVL(TO_CHAR(r.month_of_payment, ''Mon YYYY''), ''-'')',
'               )',
'            || ''</td><td class="money">''',
'            || fmt(r.previous_meter)',
'            || ''</td><td class="money">''',
'            || fmt(r.current_meter)',
'            || ''</td><td class="money">''',
'            || fmt(r.unit_consumed)',
'            || ''</td><td class="money">''',
'            || fmt(r.utility_charge)',
'            || ''</td><td class="money">''',
'            || fmt(r.rent)',
'            || ''</td><td class="money">''',
'            || fmt(r.cleaner_charge)',
'            || ''</td><td class="money">''',
'            || fmt(r.total)',
'            || ''</td><td class="money rent-paid">''',
'            || fmt(r.payment_paid)',
'            || ''</td><td class="money rent-balance">''',
'            || fmt(r.balance)',
'            || ''</td></tr>'';',
'    END LOOP;',
'',
'    -- Table footer and report closing',
'    v_html := v_html',
'        || q''~',
'            </tbody>',
'            <tfoot>',
'              <tr>',
'                <td colspan="7">GRAND TOTAL</td>',
'                <td class="money">~''',
'        || fmt(v_total)',
'        || q''~</td>',
'                <td class="money">~''',
'        || fmt(v_paid)',
'        || q''~</td>',
'                <td class="money rent-balance">~''',
'        || fmt(v_balance)',
'        || q''~</td>',
'              </tr>',
'            </tfoot>',
'          </table>',
'        </div>',
'      </div>',
'',
'      <div class="rent-foot">',
'        <span>Generated from tenant payment records</span>',
unistr('        <span>Currency: AFN \00B7 Please retain this statement for your records</span>'),
'      </div>',
'    </div>',
'    ~'';',
'',
'    RETURN v_html;',
'',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(9741624794207039)
,p_name=>'P30_TENANT_ID'
,p_item_sequence=>10
,p_display_as=>'NATIVE_HIDDEN'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'Y')).to_clob
);
end;
