prompt --application/pages/page_00015
begin
wwv_flow_imp_page.create_page(
 p_id=>15
,p_name=>'Rental Payment Registration Report'
,p_alias=>'RENTAL-PAYMENT-REGISTRATION-REPORT'
,p_step_title=>'Rental Payment Registration Report'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'03'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(9621255139318465)
,p_name=>'Rental Payment Registration Report'
,p_template=>4072358936313175081
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    RENTAL_PAYMENT_ID,',
'    RENTAL_ID,',
'    PAYMENT_DATE,',
'    MONTH_OF_PAYMENT,',
'    RENT,',
'    PREVIOUS_METER,',
'    CURRENT_METER,',
'    UNITS_CONSUMED,',
'    METER_RATE,',
'    UTILITY_CHARGE,',
'    CLEANER,',
'',
'    NVL(RENT, 0)',
'      + NVL(UTILITY_CHARGE, 0)',
'      + NVL(CLEANER, 0) AS TOTAL,',
'',
'    NVL(AMOUNT_PAID, 0) AS DUE_MONEY,',
'',
'    GREATEST(',
'        0,',
'        NVL(RENT, 0)',
'          + NVL(UTILITY_CHARGE, 0)',
'          + NVL(CLEANER, 0)',
'          - NVL(AMOUNT_PAID, 0)',
'    ) AS BALANCE,',
'',
'    CASE',
'        WHEN NVL(AMOUNT_PAID, 0) = 0 THEN ''UNPAID''',
'        WHEN NVL(AMOUNT_PAID, 0) <',
'             NVL(RENT, 0)',
'             + NVL(UTILITY_CHARGE, 0)',
'             + NVL(CLEANER, 0)',
'        THEN ''PARTIAL''',
'        ELSE ''PAID''',
'    END AS STATUS,',
'',
'    NOTES',
'',
'FROM (',
'    SELECT',
'        RENTAL_PAYMENT_ID,',
'        RENTAL_ID,',
'        PAYMENT_DATE,',
'        MONTH_OF_PAYMENT,',
'        RENT,',
'        PREVIOUS_METER,',
'        CURRENT_METER,',
'',
'        NVL(CURRENT_METER, 0)',
'          - NVL(PREVIOUS_METER, 0) AS UNITS_CONSUMED,',
'',
'        METER_RATE,',
'',
'        (',
'            NVL(CURRENT_METER, 0)',
'              - NVL(PREVIOUS_METER, 0)',
'        ) * NVL(METER_RATE, 0) AS UTILITY_CHARGE,',
