 p_id=>wwv_flow_imp.id(9440513014265122)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'payment_receipt_note'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_tenant_name VARCHAR2(200);',
'    v_paid        NUMBER := 0;',
'    v_total_due   NUMBER := 0;',
'BEGIN',
'    SELECT t.full_name',
'      INTO v_tenant_name',
'      FROM rental r',
'      JOIN tenant t',
'        ON t.tenant_id = r.tenant_id',
'     WHERE r.rental_id = :P9_RENTAL_ID;',
'',
'    SELECT NVL(SUM(pr.amount_paid), 0)',
'      INTO v_paid',
'      FROM payment_receipt pr',
'      JOIN rental_payment rp',
'        ON rp.rental_payment_id = pr.rental_payment_id',
'     WHERE rp.rental_payment_id = :P15_RENTAL_PAYMENT_ID;',
'',
'    :PXX_NOTES :=',
'        ''Tenant: '' || v_tenant_name',
'        || '' | Paid: '' || TO_CHAR(v_paid, ''FM999G999G990'')',
'        || '' AFN | Total Due: ''',
'        || TO_CHAR(NVL(:PXX_TOTAL_DUE, 0), ''FM999G999G990'')',
'        || '' AFN'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>9440513014265122
);
end;
