,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'25'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10054473062212308)
,p_plug_name=>'Tenant rent list report'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'DECLARE',
'    l_html          CLOB;',
'    l_payment_count NUMBER := 0;',
'    l_total_rent    NUMBER := 0;',
'    l_total_utility NUMBER := 0;',
'    l_total_billed  NUMBER := 0;',
'',
'    l_utility       NUMBER;',
'    l_total_due     NUMBER;',
'',
'    FUNCTION fmt_amount(p_amount NUMBER)',
'        RETURN VARCHAR2',
'    IS',
'    BEGIN',
'        RETURN TO_CHAR(',
'            NVL(p_amount, 0),',
'            ''FM999G999G999G990D00'',',
'            ''NLS_NUMERIC_CHARACTERS=''''.,''''''',
'        );',
'    END fmt_amount;',
'',
'    FUNCTION esc(p_text VARCHAR2)',
'        RETURN VARCHAR2',
'    IS',
'    BEGIN',
'        RETURN APEX_ESCAPE.HTML(NVL(p_text, ''''));',
'    END esc;',
'',
'BEGIN',
'    /*',
'       1. Calculate dashboard summary values.',
'       Utility = (current meter - previous meter) * meter rate.',
'       Negative consumption is treated as zero.',
'    */',
'    SELECT COUNT(*),',
'           NVL(SUM(NVL(rp.rent, 0)), 0),',
'           NVL(SUM(',
'               GREATEST(',
'                   NVL(rp.current_meter, 0)',
'                   - NVL(rp.previous_meter, 0),',
'                   0',
'               ) * NVL(rp.meter_rate, 0)',
'           ), 0),',
'           NVL(SUM(',
'               NVL(rp.rent, 0)',
'               + GREATEST(',
'                   NVL(rp.current_meter, 0)',
'                   - NVL(rp.previous_meter, 0),',
'                   0',
'               ) * NVL(rp.meter_rate, 0)',
'               + NVL(rp.cleaner, 0)',
'           ), 0)',
'      INTO l_payment_count,',
'           l_total_rent,',
'           l_total_utility,',
'           l_total_billed',
'      FROM rental_payment rp;',
'',
'    /*',
'       2. Start the HTML report.',
'    */',
'    l_html := TO_CLOB(q''~',
'<style>',
'.rp-report {',
'    font-family: Arial, sans-serif;',
'    color: #172033;',
'}',
'.rp-cards {',
'    display: grid;',
'    grid-template-columns: repeat(4, minmax(0, 1fr));',
'    gap: 14px;',
'    margin-bottom: 22px;',
'}',
'.rp-card {',
'    background: #ffffff;',
'    border: 1px solid #e1e8f0;',
'    border-radius: 12px;',
'    padding: 18px;',
'    box-shadow: 0 3px 10px rgba(20, 40, 70, .05);',
'}',
'.rp-label {',
'    color: #65748b;',
'    font-size: 12px;',
'    margin-bottom: 12px;',
'}',
'.rp-value {',
'    color: #173b6c;',
'    font-size: 22px;',
'    font-weight: 700;',
'    overflow-wrap: anywhere;',
'}',
'.rp-subtitle {',
'    color: #65748b;',
'    font-size: 12px;',
'    margin-top: 8px;',
'}',
'.rp-table-wrap {',
'    width: 100%;',
'    overflow-x: auto;',
'    background: #ffffff;',
'    border: 1px solid #e1e8f0;',
'    border-radius: 12px;',
'}',
'.rp-table {',
'    width: 100%;',
'    border-collapse: collapse;',
'    font-size: 12px;',
'}',
'.rp-table th {',
'    background: #173b6c;',
'    color: #ffffff;',
'    text-align: left;',
'    padding: 13px 12px;',
'    white-space: nowrap;',
'}',
'.rp-table td {',
'    padding: 12px;',
'    border-bottom: 1px solid #e8edf4;',
'    white-space: nowrap;',
'}',
'.rp-table tr:last-child td {',
'    border-bottom: none;',
'}',
'.rp-table tbody tr:hover {',
'    background: #f4f8fd;',
'}',
'.rp-status {',
'    display: inline-block;',
'    padding: 5px 9px;',
'    border-radius: 20px;',
'    font-size: 11px;',
'    font-weight: 700;',
'}',
'.rp-paid {',
'    background: #dcfce7;',
'    color: #166534;',
'}',
'.rp-pending {',
'    background: #fef3c7;',
'    color: #92400e;',
'}',
'.rp-other {',
'    background: #e5e7eb;',
'    color: #374151;',
'}',
'.rp-section-title {',
'    font-size: 17px;',
'    font-weight: 700;',
'    margin: 22px 0 12px;',
'    color: #173b6c;',
'}',
'.rp-empty {',
'    padding: 22px;',
'    text-align: center;',
'    color: #65748b;',
'}',
'@media(max-width: 850px) {',
'    .rp-cards {',
'        grid-template-columns: repeat(2, minmax(0, 1fr));',
'    }',
'}',
'@media(max-width: 480px) {',
'    .rp-cards {',
'        grid-template-columns: 1fr;',
'    }',
'}',
'</style>',
'',
'<div class="rp-report">',
'    <div class="rp-cards">',
'        <div class="rp-card">',
'            <div class="rp-label">Total Payment Records</div>',
'            <div class="rp-value">~'')',
'        || TO_CLOB(TO_CHAR(l_payment_count, ''FM999G999G999G990''))',
'        || TO_CLOB(q''~</div>',
'            <div class="rp-subtitle">All recorded payment rows</div>',
'        </div>',
'',
'        <div class="rp-card">',
'            <div class="rp-label">Total Rent</div>',
'            <div class="rp-value">AFN ~'')',
'        || TO_CLOB(fmt_amount(l_total_rent))',
'        || TO_CLOB(q''~</div>',
'            <div class="rp-subtitle">Sum of recorded rent</div>',
'        </div>',
'',
'        <div class="rp-card">',
'            <div class="rp-label">Total Utilities</div>',
'            <div class="rp-value">AFN ~'')',
'        || TO_CLOB(fmt_amount(l_total_utility))',
'        || TO_CLOB(q''~</div>',
'            <div class="rp-subtitle">Meter consumption charges</div>',
'        </div>',
'',
'        <div class="rp-card">',
'            <div class="rp-label">Total Billed</div>',
'            <div class="rp-value">AFN ~'')',
'        || TO_CLOB(fmt_amount(l_total_billed))',
'        || TO_CLOB(q''~</div>',
'            <div class="rp-subtitle">Rent + utilities + cleaner</div>',
'        </div>',
'    </div>',
'',
'    <div class="rp-section-title">Rental Payment Details</div>',
'',
'    <div class="rp-table-wrap">',
'        <table class="rp-table">',
'            <thead>',
'                <tr>',
'                    <th>Payment ID</th>',
'                    <th>Tenant</th>',
'                    <th>Phone</th>',
'                    <th>Service No.</th>',
'                    <th>Floor</th>',
'                    <th>Payment Month</th>',
'                    <th>Payment Date</th>',
'                    <th>Rent (AFN)</th>',
'                    <th>Utility (AFN)</th>',
'                    <th>Cleaner (AFN)</th>',
'                    <th>Total Due (AFN)</th>',
'                    <th>Status</th>',
'                    <th>Notes</th>',
'                </tr>',
'            </thead>',
'            <tbody>~'');',
'',
'    /*',
'       3. Add one table row per payment record.',
'    */',
'    FOR r IN (',
'        SELECT',
'            rp.rental_payment_id,',
'            rp.month_of_payment,',
'            rp.payment_date,',
'            rp.rent,',
'            rp.previous_meter,',
'            rp.current_meter,',
'            rp.meter_rate,',
'            rp.cleaner,',
'            rp.status,',
'            rp.notes,',
'            t.tenant_name,',
'            t.phone,',
'            rs.services_no,',
'            rs.floor_no',
'        FROM rental_payment rp',
'        LEFT JOIN rental r',
'            ON r.rental_id = rp.rental_id',
'        LEFT JOIN tenant t',
'            ON t.tenant_id = r.tenant_id',
'        LEFT JOIN rental_services rs',
'            ON rs.rental_service_id = r.rental_service_id',
'        ORDER BY rp.payment_date DESC NULLS LAST,',
'                 rp.rental_payment_id DESC',
'    )',
'    LOOP',
'        l_utility :=',
'            GREATEST(',
'                NVL(r.current_meter, 0)',
'                - NVL(r.previous_meter, 0),',
'                0',
'            ) * NVL(r.meter_rate, 0);',
'',
'        l_total_due :=',
'            NVL(r.rent, 0)',
'            + l_utility',
'            + NVL(r.cleaner, 0);',
'',
'        l_html := l_html',
'            || TO_CLOB(''<tr><td>'')',
'            || TO_CLOB(esc(TO_CHAR(r.rental_payment_id)))',
'            || TO_CLOB(''</td><td>'')',
'            || TO_CLOB(esc(r.tenant_name))',
'            || TO_CLOB(''</td><td>'')',
'            || TO_CLOB(esc(r.phone))',
'            || TO_CLOB(''</td><td>'')',
'            || TO_CLOB(esc(r.services_no))',
'            || TO_CLOB(''</td><td>'')',
'            || TO_CLOB(esc(r.floor_no))',
'            || TO_CLOB(''</td><td>'')',
'            || TO_CLOB(',
'                CASE',
'                    WHEN r.month_of_payment IS NOT NULL THEN',
'                        esc(TO_CHAR(r.month_of_payment, ''FMMonth YYYY''))',
'                    ELSE',
'                        ''-''',
'                END',
'            )',
'            || TO_CLOB(''</td><td>'')',
'            || TO_CLOB(',
'                CASE',
'                    WHEN r.payment_date IS NOT NULL THEN',
'                        esc(TO_CHAR(r.payment_date, ''DD-MON-YYYY''))',
'                    ELSE',
'                        ''-''',
'                END',
'            )',
'            || TO_CLOB(''</td><td style="text-align:right">'')',
'            || TO_CLOB(fmt_amount(r.rent))',
'            || TO_CLOB(''</td><td style="text-align:right">'')',
'            || TO_CLOB(fmt_amount(l_utility))',
'            || TO_CLOB(''</td><td style="text-align:right">'')',
'            || TO_CLOB(fmt_amount(r.cleaner))',
'            || TO_CLOB(''</td><td style="text-align:right;font-weight:bold">'')',
'            || TO_CLOB(fmt_amount(l_total_due))',
'            || TO_CLOB(''</td><td><span class="rp-status '');',
'',
'        IF UPPER(TRIM(NVL(r.status, ''''))) = ''PAID'' THEN',
'            l_html := l_html || TO_CLOB(''rp-paid'');',
'        ELSIF UPPER(TRIM(NVL(r.status, ''''))) IN',
'              (''PENDING'', ''UNPAID'', ''PARTIAL'') THEN',
'            l_html := l_html || TO_CLOB(''rp-pending'');',
'        ELSE',
'            l_html := l_html || TO_CLOB(''rp-other'');',
'        END IF;',
'',
'        l_html := l_html',
'            || TO_CLOB(''">'')',
'            || TO_CLOB(esc(r.status))',
'            || TO_CLOB(''</span></td><td>'')',
'            || TO_CLOB(esc(r.notes))',
'            || TO_CLOB(''</td></tr>'');',
'    END LOOP;',
'',
'    /*',
'       4. Show a message when there are no payment rows.',
'    */',
'    IF l_payment_count = 0 THEN',
'        l_html := l_html',
'            || TO_CLOB(',
'                ''<tr><td colspan="13" class="rp-empty">''',
'                || ''No rental payment records found.''',
'                || ''</td></tr>''',
'            );',
'    END IF;',
'',
'    /*',
'       5. Close the HTML and RETURN the CLOB.',
'    */',
'    l_html := l_html || TO_CLOB(q''~',
'            </tbody>',
'        </table>',
'    </div>',
'</div>',
'~'');',
'',
'    RETURN l_html;',
'',
'END;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
end;
/
prompt --application/pages/page_00025
begin
wwv_flow_imp_page.create_page(
 p_id=>25
,p_name=>'Emplyee list'
,p_alias=>'EMPLYEE-LIST'
,p_step_title=>'Emplyee list'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'25'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10054505559212309)
,p_plug_name=>'All Emplyee List'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'DECLARE',
'    l_html          CLOB;',
'    l_employee_count NUMBER := 0;',
'    l_total_salary   NUMBER := 0;',
'    l_total_paid     NUMBER := 0;',
'    l_total_balance  NUMBER := 0;',
'',
'    l_salary_total   NUMBER;',
'    l_paid_amount    NUMBER;',
'    l_balance        NUMBER;',
'',
'    FUNCTION fmt_amount(p_amount NUMBER)',
'        RETURN VARCHAR2',
'    IS',
'    BEGIN',
'        RETURN TO_CHAR(',
'            NVL(p_amount, 0),',
'            ''FM999G999G999G990D00'',',
'            ''NLS_NUMERIC_CHARACTERS=''''.,''''''',
'        );',
'    END fmt_amount;',
'',
'    FUNCTION esc(p_text VARCHAR2)',
'        RETURN VARCHAR2',
'    IS',
'    BEGIN',
'        RETURN APEX_ESCAPE.HTML(NVL(p_text, ''''));',
'    END esc;',
'',
'BEGIN',
'    /*',
'       1. Calculate employee salary summary.',
'',
'       Total salary = AMOUNT + BONUS',
'       Balance = Total salary - PAID',
'    */',
'    SELECT COUNT(*),',
'           NVL(SUM(NVL(s.amount, 0) + NVL(s.bonus, 0)), 0),',
'           NVL(SUM(NVL(s.paid, 0)), 0),',
'           NVL(SUM(',
'               GREATEST(',
'                   NVL(s.amount, 0)',
'                   + NVL(s.bonus, 0)',
'                   - NVL(s.paid, 0),',
'                   0',
'               )',
'           ), 0)',
'      INTO l_employee_count,',
'           l_total_salary,',
'           l_total_paid,',
'           l_total_balance',
'      FROM emp e',
'      LEFT JOIN salary s',
'        ON s.emp_id = e.emp_id;',
'',
'    /*',
'       2. Start report HTML.',
'    */',
'    l_html := TO_CLOB(q''~',
'<style>',
'.emp-report {',
'    font-family: Arial, sans-serif;',
'    color: #172033;',
'}',
'.emp-cards {',
'    display: grid;',
'    grid-template-columns: repeat(4, minmax(0, 1fr));',
'    gap: 14px;',
'    margin-bottom: 22px;',
'}',
'.emp-card {',
'    background: #ffffff;',
'    border: 1px solid #e1e8f0;',
'    border-radius: 12px;',
'    padding: 18px;',
'    box-shadow: 0 3px 10px rgba(20, 40, 70, .05);',
'}',
'.emp-label {',
'    color: #65748b;',
'    font-size: 12px;',
'    margin-bottom: 12px;',
'}',
'.emp-value {',
'    color: #173b6c;',
'    font-size: 22px;',
'    font-weight: 700;',
'    overflow-wrap: anywhere;',
'}',
'.emp-subtitle {',
'    color: #65748b;',
'    font-size: 12px;',
'    margin-top: 8px;',
'}',
'.emp-table-wrap {',
'    width: 100%;',
'    overflow-x: auto;',
'    background: #ffffff;',
'    border: 1px solid #e1e8f0;',
'    border-radius: 12px;',
'}',
'.emp-table {',
'    width: 100%;',
'    border-collapse: collapse;',
'    font-size: 12px;',
'}',
'.emp-table th {',
'    background: #173b6c;',
'    color: #ffffff;',
'    text-align: left;',
'    padding: 13px 12px;',
'    white-space: nowrap;',
'}',
'.emp-table td {',
'    padding: 12px;',
'    border-bottom: 1px solid #e8edf4;',
'    white-space: nowrap;',
'}',
'.emp-table tr:last-child td {',
'    border-bottom: none;',
'}',
'.emp-table tbody tr:hover {',
'    background: #f4f8fd;',
'}',
'.emp-status {',
'    display: inline-block;',
'    padding: 5px 9px;',
'    border-radius: 20px;',
'    font-size: 11px;',
'    font-weight: 700;',
'}',
'.emp-paid {',
'    background: #dcfce7;',
'    color: #166534;',
'}',
'.emp-pending {',
'    background: #fef3c7;',
'    color: #92400e;',
'}',
'.emp-other {',
'    background: #e5e7eb;',
'    color: #374151;',
'}',
'.emp-section-title {',
'    font-size: 17px;',
'    font-weight: 700;',
'    margin: 22px 0 12px;',
'    color: #173b6c;',
'}',
'.emp-empty {',
'    padding: 22px;',
'    text-align: center;',
'    color: #65748b;',
'}',
'@media(max-width: 850px) {',
'    .emp-cards {',
'        grid-template-columns: repeat(2, minmax(0, 1fr));',
'    }',
'}',
'@media(max-width: 480px) {',
'    .emp-cards {',
'        grid-template-columns: 1fr;',
'    }',
'}',
'</style>',
'',
'<div class="emp-report">',
'    <div class="emp-cards">',
'        <div class="emp-card">',
'            <div class="emp-label">Total Employees</div>',
'            <div class="emp-value">~'')',
'        || TO_CLOB(TO_CHAR(',
'            l_employee_count, ''FM999G999G999G990''',
'        ))',
'        || TO_CLOB(q''~</div>',
'            <div class="emp-subtitle">Registered employees</div>',
'        </div>',
'',
'        <div class="emp-card">',
'            <div class="emp-label">Total Salary</div>',
'            <div class="emp-value">AFN ~'')',
'        || TO_CLOB(fmt_amount(l_total_salary))',
'        || TO_CLOB(q''~</div>',
'            <div class="emp-subtitle">Salary plus bonuses</div>',
'        </div>',
'',
'        <div class="emp-card">',
'            <div class="emp-label">Total Paid</div>',
'            <div class="emp-value">AFN ~'')',
'        || TO_CLOB(fmt_amount(l_total_paid))',
'        || TO_CLOB(q''~</div>',
'            <div class="emp-subtitle">Recorded salary payments</div>',
'        </div>',
'',
'        <div class="emp-card">',
'            <div class="emp-label">Total Balance</div>',
'            <div class="emp-value">AFN ~'')',
'        || TO_CLOB(fmt_amount(l_total_balance))',
'        || TO_CLOB(q''~</div>',
'            <div class="emp-subtitle">Remaining salary balance</div>',
'        </div>',
'    </div>',
'',
'    <div class="emp-section-title">Employee Salary Details</div>',
'',
'    <div class="emp-table-wrap">',
'        <table class="emp-table">',
'            <thead>',
'                <tr>',
'                    <th>Employee ID</th>',
'                    <th>Employee Name</th>',
'                    <th>Phone</th>',
'                    <th>Total Salary (AFN)</th>',
'                    <th>Paid (AFN)</th>',
'                    <th>Balance (AFN)</th>',
'                    <th>Status</th>',
'                </tr>',
'            </thead>',
'            <tbody>~'');',
'',
'    /*',
'       3. Display one row per employee.',
'',
'       If an employee has multiple salary records,',
'       aggregate those records to show one employee row.',
'    */',
'    FOR r IN (',
'        SELECT',
'            e.emp_id,',
'            e.emp_name,',
'            e.phone,',
'            NVL(SUM(NVL(s.amount, 0) + NVL(s.bonus, 0)), 0)',
'                AS total_salary,',
'            NVL(SUM(NVL(s.paid, 0)), 0)',
'                AS total_paid',
'        FROM emp e',
'        LEFT JOIN salary s',
'            ON s.emp_id = e.emp_id',
'        GROUP BY',
'            e.emp_id,',
'            e.emp_name,',
'            e.phone',
'        ORDER BY e.emp_id',
'    )',
'    LOOP',
'        l_salary_total := r.total_salary;',
'        l_paid_amount  := r.total_paid;',
'',
'        l_balance := GREATEST(',
'            l_salary_total - l_paid_amount,',
'            0',
'        );',
'',
'        l_html := l_html',
'            || TO_CLOB(''<tr><td>'')',
'            || TO_CLOB(esc(TO_CHAR(r.emp_id)))',
'            || TO_CLOB(''</td><td>'')',
'            || TO_CLOB(esc(r.emp_name))',
'            || TO_CLOB(''</td><td>'')',
'            || TO_CLOB(esc(r.phone))',
'            || TO_CLOB(''</td><td style="text-align:right">'')',
'            || TO_CLOB(fmt_amount(l_salary_total))',
'            || TO_CLOB(''</td><td style="text-align:right">'')',
'            || TO_CLOB(fmt_amount(l_paid_amount))',
'            || TO_CLOB(''</td><td style="text-align:right;font-weight:bold">'')',
'            || TO_CLOB(fmt_amount(l_balance))',
'            || TO_CLOB(''</td><td><span class="emp-status '');',
'',
'        IF l_balance = 0 AND l_salary_total > 0 THEN',
'            l_html := l_html || TO_CLOB(''emp-paid'');',
'        ELSIF l_paid_amount > 0 AND l_balance > 0 THEN',
'            l_html := l_html || TO_CLOB(''emp-pending'');',
'        ELSE',
'            l_html := l_html || TO_CLOB(''emp-other'');',
'        END IF;',
'',
'        l_html := l_html',
'            || TO_CLOB(''">'');',
'',
'        IF l_balance = 0 AND l_salary_total > 0 THEN',
'            l_html := l_html || TO_CLOB(''Paid'');',
'        ELSIF l_paid_amount > 0 AND l_balance > 0 THEN',
'            l_html := l_html || TO_CLOB(''Partial'');',
'        ELSIF l_salary_total = 0 THEN',
'            l_html := l_html || TO_CLOB(''No Salary'');',
'        ELSE',
'            l_html := l_html || TO_CLOB(''Unpaid'');',
'        END IF;',
'',
'        l_html := l_html',
'            || TO_CLOB(''</span></td></tr>'');',
'    END LOOP;',
'',
'    /*',
'       4. Display message if there are no employees.',
'    */',
'    IF l_employee_count = 0 THEN',
'        l_html := l_html',
'            || TO_CLOB(',
'                ''<tr><td colspan="7" class="emp-empty">''',
'                || ''No employee records found.''',
'                || ''</td></tr>''',
'            );',
'    END IF;',
'',
'    /*',
'       5. Close HTML and return CLOB.',
'    */',
'    l_html := l_html || TO_CLOB(q''~',
'            </tbody>',
'        </table>',
'    </div>',
'</div>',
'~'');',
'',
'    RETURN l_html;',
'',
'END;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
end;
/
prompt --application/pages/page_00026
begin
wwv_flow_imp_page.create_page(
 p_id=>26
,p_name=>'Emplyee salary Bill'
,p_alias=>'EMPLYEE-SALARY-BILL'
,p_step_title=>'Emplyee salary Bill'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'25'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10054688600212310)
,p_plug_name=>'Employee Bill'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4501440665235496320
,p_plug_display_sequence=>20
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'DECLARE',
'    l_html       CLOB;',
'    l_emp_id     NUMBER;',
'    l_emp_name   VARCHAR2(150);',
'    l_salary     NUMBER := 0;',
'    l_paid       NUMBER := 0;',
'    l_balance    NUMBER := 0;',
'',
'    FUNCTION fmt(p_value NUMBER) RETURN VARCHAR2 IS',
'    BEGIN',
'        RETURN TO_CHAR(',
'            NVL(p_value, 0),',
'            ''FM999G999G999G990D00'',',
'            ''NLS_NUMERIC_CHARACTERS=''''.,''''''',
'        );',
'    END fmt;',
'',
'BEGIN',
'    -- Check employee selection',
'    IF :P26_EMPLOYEESALARY IS NULL THEN',
'        RETURN q''~',
'            <div class="salary-notice">',
'                Please select an employee to display the salary bill.',
'            </div>',
'        ~'';',
'    END IF;',
'',
'    -- Get employee information',
'    SELECT emp_id, emp_name',
'      INTO l_emp_id, l_emp_name',
'      FROM emp',
'     WHERE emp_id = :P26_EMPLOYEESALARY;',
'',
'    -- Calculate salary and paid totals',
'    SELECT NVL(SUM(amount), 0),',
'           NVL(SUM(paid), 0)',
'      INTO l_salary, l_paid',
'      FROM salary',
'     WHERE emp_id = :P26_EMPLOYEESALARY;',
'',
'    -- Calculate remaining balance',
'    l_balance := l_salary - l_paid;',
'',
'    -- Start report',
'    l_html := q''~',
'    <style>',
'      .salary-report {',
'        font-family: Arial, sans-serif;',
'        color: #17243b;',
'        background: #fff;',
'        border: 1px solid #e2e8f0;',
'        border-radius: 16px;',
'        overflow: hidden;',
'        box-shadow: 0 8px 28px rgba(20,45,80,.08);',
'      }',
'',
'      .salary-head {',
'        padding: 28px;',
'        background: linear-gradient(120deg,#12345a,#2468a0);',
'        color: #fff;',
'        display: flex;',
'        justify-content: space-between;',
'        gap: 16px;',
'        align-items: center;',
'      }',
'',
'      .salary-head h2 {',
'        margin: 0 0 8px;',
'        font-size: 25px;',
'      }',
'',
'      .salary-head p {',
'        margin: 0;',
'        color: #dbeafe;',
'        font-size: 13px;',
'      }',
'',
'      .salary-print {',
'        background: #fff;',
'        color: #17416c;',
'        border: 0;',
'        border-radius: 9px;',
'        padding: 12px 18px;',
'        font-weight: bold;',
'        cursor: pointer;',
'        white-space: nowrap;',
'      }',
'',
'      .salary-body { padding: 22px; }',
'',
'      .salary-employee {',
'        padding: 18px;',
'        margin-bottom: 22px;',
'        border: 1px solid #e3eaf3;',
'        border-radius: 12px;',
'        background: #f8fbff;',
'      }',
'',
'      .salary-employee span {',
'        display: block;',
'        color: #64748b;',
'        font-size: 12px;',
'        margin-bottom: 7px;',
'      }',
'',
'      .salary-employee strong {',
'        color: #173b6c;',
'        font-size: 16px;',
'      }',
'',
'      .salary-summary {',
'        display: grid;',
'        grid-template-columns: repeat(3,minmax(0,1fr));',
'        gap: 12px;',
'        margin-bottom: 22px;',
'      }',
'',
'      .salary-card {',
'        padding: 18px;',
'        border: 1px solid #e3eaf3;',
'        border-radius: 12px;',
'        background: #f8fbff;',
'        min-width: 0;',
'      }',
'',
'      .salary-card span {',
'        display: block;',
'        color: #64748b;',
'        font-size: 12px;',
'        margin-bottom: 9px;',
'      }',
'',
'      .salary-card strong {',
'        font-size: 21px;',
'        color: #173b6c;',
'        overflow-wrap: anywhere;',
'      }',
'',
'      .salary-table-wrap {',
'        width: 100%;',
'        overflow-x: auto;',
'      }',
'',
'      .salary-table {',
'        width: 100%;',
'        border-collapse: collapse;',
'        font-size: 13px;',
'      }',
'',
'      .salary-table th {',
'        background: #edf4fc;',
'        color: #234568;',
'        text-align: left;',
'        padding: 14px;',
'        border-bottom: 1px solid #dbe5f0;',
'      }',
'',
'      .salary-table td {',
'        padding: 15px 14px;',
'        border-bottom: 1px solid #edf1f6;',
'      }',
'',
'      .salary-table .money {',
'        text-align: right;',
'        white-space: nowrap;',
'      }',
'',
'      .salary-table tfoot td {',
'        background: #edf4fc;',
'        font-weight: bold;',
'      }',
'',
'      .salary-paid {',
'        color: #16805d !important;',
'      }',
'',
'      .salary-balance {',
'        color: #c24145 !important;',
'      }',
'',
'      .salary-notice {',
'        padding: 18px;',
'        margin: 20px;',
'        background: #fff7e6;',
'        border: 1px solid #f3d9a5;',
'        border-radius: 10px;',
'        color: #805b16;',
'      }',
'',
'      .salary-foot {',
'        display: flex;',
'        justify-content: space-between;',
'        gap: 12px;',
'        padding: 18px 22px;',
'        color: #64748b;',
'        font-size: 11px;',
'        border-top: 1px solid #e5ebf3;',
'      }',
'',
'      @media(max-width:700px) {',
'        .salary-head {',
'          align-items: flex-start;',
'          flex-direction: column;',
'        }',
'        .salary-summary {',
'          grid-template-columns: 1fr;',
'        }',
'        .salary-body { padding: 12px; }',
'      }',
'',
'      @media print {',
'        @page { size: portrait; margin: 12mm; }',
'',
'        body * { visibility: hidden !important; }',
'',
'        .salary-report,',
'        .salary-report * {',
'          visibility: visible !important;',
'        }',
'',
'        .salary-report {',
'          position: absolute !important;',
'          left: 0 !important;',
'          top: 0 !important;',
'          width: 100% !important;',
'          border: 0 !important;',
'          box-shadow: none !important;',
'          border-radius: 0 !important;',
'        }',
'',
'        .salary-print,',
'        .t-Header,',
'        .t-Footer,',
'        .t-Body-nav,',
'        .t-Body-actions,',
'        .t-Body-title {',
'          display: none !important;',
'        }',
'',
'        .salary-head {',
'          background: #12345a !important;',
'          color: #fff !important;',
'          print-color-adjust: exact;',
'          -webkit-print-color-adjust: exact;',
'        }',
'',
'        .salary-table th,',
'        .salary-table tfoot td {',
'          print-color-adjust: exact;',
'          -webkit-print-color-adjust: exact;',
'        }',
'      }',
'    </style>',
'',
'    <div class="salary-report">',
'',
'      <div class="salary-head">',
'        <div>',
'          <h2>Employee Salary Bill</h2>',
unistr('          <p>Sarvary Building Management System \00B7 Employee Payroll Statement</p>'),
'        </div>',
'',
'        <button type="button"',
'                class="salary-print"',
'                onclick="window.print()">',
'          &#128438; Print Report',
'        </button>',
'      </div>',
'',
'      <div class="salary-body">',
'',
'        <div class="salary-employee">',
'          <span>Employee ID</span>',
'          <strong>~''',
'        || APEX_ESCAPE.HTML(TO_CHAR(l_emp_id))',
'        || q''~</strong>',
'',
'          <div style="height:14px"></div>',
'',
'          <span>Employee Name</span>',
'          <strong>~''',
'        || APEX_ESCAPE.HTML(l_emp_name)',
'        || q''~</strong>',
'        </div>',
'',
'        <div class="salary-summary">',
'',
'          <div class="salary-card">',
'            <span>Total Salary</span>',
'            <strong>~''',
'        || fmt(l_salary)',
'        || q''~ AFN</strong>',
'          </div>',
'',
'          <div class="salary-card">',
'            <span>Total Paid</span>',
'            <strong class="salary-paid">~''',
'        || fmt(l_paid)',
'        || q''~ AFN</strong>',
'          </div>',
'',
'          <div class="salary-card">',
'            <span>Outstanding Balance</span>',
'            <strong class="salary-balance">~''',
'        || fmt(l_balance)',
'        || q''~ AFN</strong>',
'          </div>',
'',
'        </div>',
'',
'        <div class="salary-table-wrap">',
'          <table class="salary-table">',
'            <thead>',
'              <tr>',
'                <th>Employee ID</th>',
'                <th>Employee Name</th>',
'                <th class="money">Salary (AFN)</th>',
'                <th class="money">Paid (AFN)</th>',
'                <th class="money">Balance (AFN)</th>',
'              </tr>',
'            </thead>',
'',
'            <tbody>',
'              <tr>',
'                <td>~''',
'        || APEX_ESCAPE.HTML(TO_CHAR(l_emp_id))',
'        || q''~</td>',
'',
'                <td>~''',
'        || APEX_ESCAPE.HTML(l_emp_name)',
'        || q''~</td>',
'',
'                <td class="money">~''',
'        || fmt(l_salary)',
'        || q''~</td>',
'',
'                <td class="money salary-paid">~''',
'        || fmt(l_paid)',
'        || q''~</td>',
'',
'                <td class="money salary-balance">~''',
'        || fmt(l_balance)',
'        || q''~</td>',
'              </tr>',
'            </tbody>',
'',
'            <tfoot>',
'              <tr>',
'                <td colspan="2">GRAND TOTAL</td>',
'                <td class="money">~''',
'        || fmt(l_salary)',
'        || q''~</td>',
'                <td class="money salary-paid">~''',
'        || fmt(l_paid)',
'        || q''~</td>',
'                <td class="money salary-balance">~''',
'        || fmt(l_balance)',
'        || q''~</td>',
'              </tr>',
'            </tfoot>',
'          </table>',
'        </div>',
'',
'      </div>',
'',
'      <div class="salary-foot">',
'        <span>Generated from employee salary records</span>',
unistr('        <span>Currency: AFN \00B7 Please retain this statement</span>'),
'      </div>',
'',
'    </div>',
'    ~'';',
'',
'    RETURN l_html;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN q''~',
'            <div class="salary-notice">',
'                Employee not found. Please select a valid employee.',
'            </div>',
'        ~'';',
'END;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
