wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10486928492496502)
,p_plug_name=>'New'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4501440665235496320
,p_plug_display_sequence=>10
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    a       NUMBER;',
'    l_html  CLOB;',
'BEGIN',
'    IF :P27_USER IS NULL THEN',
'        RETURN ''<div class="t-Alert t-Alert--warning">',
'                    Please select a username first.',
'                </div>'';',
'    END IF;',
'',
'    SELECT COUNT(*)',
'      INTO a',
'      FROM USER_RIGHT',
'     WHERE UPPER(USERNAME) = UPPER(:P27_USER);',
'',
'    IF a = 0 THEN',
'        FOR i IN (SELECT RIGHT_ID FROM RIGHTS) LOOP',
'            INSERT INTO USER_RIGHT (',
'                RIGHT_ID,',
'                USERNAME,',
'                SELECT_ALLOWED,',
'                INSERT_ALLOWED,',
'                UPDATE_ALLOWED,',
'                DELETE_ALLOWED',
'            )',
'            VALUES (',
'                i.RIGHT_ID,',
'                :P27_USER,',
'                ''N'',',
'                ''N'',',
'                ''N'',',
'                ''N''',
'            );',
'        END LOOP;',
'',
'        l_html := ''<div class="t-Alert t-Alert--success">',
'                       Permissions created successfully.',
'                   </div>'';',
'    ELSE',
'        l_html := ''<div class="t-Alert t-Alert--info">',
'                       Permission records already exist for this user.',
'                   </div>'';',
'    END IF;',
'',
'    RETURN l_html;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        RETURN ''<div class="t-Alert t-Alert--danger">',
'                    Error while creating permissions.',
'                </div>'';',
'END;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
